// Embedded Latin-1 subsets of DejaVu Sans; original copyright and license are retained in each font's name table.
const DOSSIER_FONT_REGULAR='';
const DOSSIER_FONT_BOLD='';
/**
 * Build a complete, source-linked district dossier in memory.
 * No windows, print dialogs, network calls, or downloads are initiated here.
 * The caller may turn doc.output('blob') into a normal download link.
 */
export function createDistrictPDF(data, districtId) {
  const JsPDF = globalThis.jspdf && globalThis.jspdf.jsPDF;
  if (!JsPDF) throw new Error('The PDF engine has not loaded. Please try the download again.');
  const id = Number(districtId);
  const list = value => Array.isArray(value) ? value : [];
  const find = value => list(value).find(x => Number(x.district ?? x.id) === id);
  const election = find(data.elections?.districts);
  if (!election) throw new Error(`District ${districtId} is not present in this dataset.`);
  const finance = find(data.finance?.districts) || {};
  const census = find(data.census?.districts) || {};
  const directory = find(data.directory?.districts) || {};
  const geometry = find(data.geometry?.districts) || {};
  const overlay = find(data.overlays?.districts) || {};
  const research = find(data.research?.districts) || {};
  const profile = find(data.issueEvidence?.profiles) || find(data.profiles?.profiles) || find(data.profiles?.districts) || find(data.profiles) || {};
  const migration = data.migrationFresh || data.migration || data.freshMigration || {};
  const metrics = list(census.metrics);
  const issues = list(data.issueEvidence?.issues).length ? data.issueEvidence.issues : list(data.issuePlan);
  const allEvidence = list(data.issueEvidence?.evidence).length ? data.issueEvidence.evidence : list(data.issueEvidence?.records);
  const evidence = allEvidence.filter(x => Number(x.district) === id);
  const number = (v, digits = 0) => v === null || v === undefined || !Number.isFinite(Number(v)) ? 'Not available' : Number(v).toLocaleString('en-US', {maximumFractionDigits: digits, minimumFractionDigits: digits});
  const money = v => v === null || v === undefined ? 'Not available' : '$' + number(v, 2);
  const plain = value => String(value ?? '').replace(/\r\n?/g, '\n').replace(/[\u2010-\u2015\u2212]/g, '-').replace(/[\u2018\u2019]/g, "'").replace(/[\u201c\u201d]/g, '"').replace(/\u2026/g, '...').replace(/[\u00a0\u202f]/g, ' ').replace(/\u2192/g, ' to ').replace(/[\u2022\u25cf]/g, '-').replace(/[^\x20-\x7e\xa0-\xff\n]/g, ' ').replace(/[ \t]+/g, ' ').trim();
  const titleCase = value => plain(value).replace(/_/g, ' ');
  const urlOK = value => /^https?:\/\//i.test(String(value || ''));
  const date = value => plain(value || 'Not stated');
  const built = data.meta?.builtAt || data.issueEvidence?.meta?.builtAt || '2026-11-23';
  const doc = new JsPDF({orientation: 'portrait', unit: 'pt', format: 'a4', compress: true, putOnlyUsedFonts: true});
  doc.addFileToVFS('DossierSans-Regular.ttf', DOSSIER_FONT_REGULAR);
  doc.addFont('DossierSans-Regular.ttf', 'DossierSans', 'normal');
  doc.addFileToVFS('DossierSans-Bold.ttf', DOSSIER_FONT_BOLD);
  doc.addFont('DossierSans-Bold.ttf', 'DossierSans', 'bold');
  doc.setProperties({title: `The Sixty-Three | District ${id} dossier`, subject: 'Sourced New York State Senate district research', author: 'The Sixty-Three', creator: 'The Sixty-Three terminal', keywords: `New York, State Senate, District ${id}, elections, sources`});
  if (doc.setLanguage) doc.setLanguage('en-US');
  const W = doc.internal.pageSize.getWidth(), H = doc.internal.pageSize.getHeight();
  const M = 42, CW = W - M * 2, TOP = 73, BOTTOM = H - 45;
  const C = {ink: [22, 29, 35], black: [11, 16, 21], gold: [169, 129, 58], paleGold: [239, 231, 213], muted: [87, 99, 109], line: [218, 222, 225], light: [246, 247, 248], white: [255, 255, 255]};
  let y = TOP, runningTitle = 'District dossier';
  const bookmarks = [];
  const sourceMap = new Map(), sourceRows = [];
  const globalSources = [...list(data.handoff?.sources), ...list(data.research?.source_registry), ...list(data.issueEvidence?.sources), ...list(migration.sources), ...list(data.overlays?.metadata?.sources)];
  const sourceById = new Map(globalSources.map(s => [String(s.id), s]));
  const sourceByUrl = new Map(globalSources.map(s => [s.sourceUrl || s.url, s]));
  function font(size = 10, style = 'normal', color = C.ink) { doc.setFont('DossierSans', style); doc.setFontSize(size); doc.setTextColor(...color); }
  function topHeader() {
    doc.setFillColor(...C.black); doc.rect(0, 0, W, 47, 'F');
    font(9, 'bold', C.paleGold); doc.text('THE SIXTY-THREE', M, 24);
    font(8, 'normal', [200, 206, 211]); doc.text(`SD ${String(id).padStart(2, '0')}  /  ${plain(runningTitle)}`, W - M, 24, {align: 'right'});
    doc.setDrawColor(...C.gold); doc.setLineWidth(1); doc.line(M, 36, W - M, 36);
  }
  function newPage() { doc.addPage(); topHeader(); y = TOP; }
  function ensure(h = 18) { if (y + h > BOTTOM) newPage(); }
  function paragraph(value, options = {}) {
    if (value === null || value === undefined || value === '') return;
    const size = options.size || 9.8, lh = options.lineHeight || size * 1.38;
    const x = options.x ?? M, width = options.width || CW, color = options.color || C.ink;
    font(size, options.bold ? 'bold' : 'normal', color);
    const paragraphs = plain(value).split('\n');
    for (let p = 0; p < paragraphs.length; p++) {
      const lines = doc.splitTextToSize(paragraphs[p] || ' ', width);
      for (const line of lines) {
        ensure(lh); font(size, options.bold ? 'bold' : 'normal', color); doc.text(line, x, y + size * 0.82); y += lh;
      }
      if (p < paragraphs.length - 1) y += 3;
    }
    y += options.after ?? 7;
  }
  function section(code, title, intro, freshPage = true) {
    runningTitle = title;
    if (freshPage && y > TOP + 100) newPage();
    else if (freshPage && y > TOP + 10) { topHeader(); y += 16; }
    ensure(64); bookmarks.push({title: `${code} ${title}`, page: doc.internal.getNumberOfPages()});
    if (doc.outline?.add) doc.outline.add(null, `${code} ${title}`, {pageNumber: doc.internal.getNumberOfPages()});
    font(9, 'bold', C.gold); doc.text(`${code}  /  DISTRICT ${id}`, M, y + 8); y += 23;
    font(22, 'bold'); doc.text(plain(title), M, y + 17); y += 32;
    if (intro) paragraph(intro, {size: 9.5, color: C.muted, after: 12});
  }
  function subheading(text) { ensure(42); y += 6; font(12, 'bold'); doc.text(plain(text), M, y + 10); y += 24; }
  function rule() { ensure(9); doc.setDrawColor(...C.line); doc.setLineWidth(0.5); doc.line(M, y, W - M, y); y += 11; }
  function table(headers, values, ratios, options = {}) {
    if (!values.length) return;
    const size = options.size || 8.6, lh = size * 1.28, pad = options.pad || 6;
    const widths = (ratios || headers.map(() => 1)).map(r => CW * r / (ratios || headers.map(() => 1)).reduce((a, b) => a + b, 0));
    let headerHeight = 0;
    function head() {
      font(size, 'bold', C.white);
      const lines = headers.map((h, i) => doc.splitTextToSize(plain(h), widths[i] - pad * 2));
      headerHeight = Math.max(...lines.map(l => l.length)) * lh + pad * 2;
      ensure(headerHeight + lh + pad * 2);
      doc.setFillColor(...C.ink); doc.rect(M, y, CW, headerHeight, 'F');
      let x = M;
      lines.forEach((ls, i) => { font(size, 'bold', C.white); doc.setLineHeightFactor(lh / size); doc.text(ls, x + pad, y + pad + size * 0.82); x += widths[i]; });
      y += headerHeight;
    }
    head();
    values.forEach((value, rowIndex) => {
      font(size);
      const cells = headers.map((_, i) => doc.splitTextToSize(plain(value[i] ?? 'Not available'), widths[i] - pad * 2));
      const maxLines = Math.max(1, ...cells.map(c => c.length));
      let offset = 0;
      while (offset < maxLines) {
        let fit = Math.floor((BOTTOM - y - pad * 2) / lh);
        if (fit < 2 || (offset === 0 && maxLines <= 12 && fit < maxLines)) { newPage(); head(); fit = Math.floor((BOTTOM - y - pad * 2) / lh); }
        const count = Math.max(1, Math.min(maxLines - offset, fit));
        const height = count * lh + pad * 2;
        doc.setFillColor(...(rowIndex % 2 ? C.white : C.light)); doc.rect(M, y, CW, height, 'F');
        let x = M;
        cells.forEach((lines, i) => { const chunk = lines.slice(offset, offset + count); font(size); doc.setLineHeightFactor(lh / size); if (chunk.length) doc.text(chunk, x + pad, y + pad + size * 0.82); x += widths[i]; });
        doc.setDrawColor(...C.line); doc.setLineWidth(0.35); doc.line(M, y + height, W - M, y + height);
        y += height; offset += count;
        if (offset < maxLines) { newPage(); head(); }
      }
    });
    y += 10;
  }
  function source(url, title, meta = {}) {
    if (!urlOK(url)) return '';
    if (sourceMap.has(url)) {
      const entry = sourceMap.get(url);
      if (meta.publishedAt) entry.dates.add(plain(meta.publishedAt));
      if (meta.eventDate) entry.events.add(plain(meta.eventDate));
      if (meta.retrievedAt) entry.retrievals.add(plain(meta.retrievedAt));
      return entry.ref;
    }
    const known = sourceByUrl.get(url) || {};
    const entry = {ref: `R${String(sourceRows.length + 1).padStart(3, '0')}`, url: String(url), title: plain(title || known.title || 'Source record'), publisher: plain(meta.publisher || known.publisher || ''), dates: new Set(), events: new Set(), retrievals: new Set(), status: plain(meta.status || known.verificationStatus || '')};
    if (meta.publishedAt || known.publishedAt || known.sourceUpdatedAt || known.sourceDate) entry.dates.add(plain(meta.publishedAt || known.publishedAt || known.sourceUpdatedAt || known.sourceDate));
    if (meta.eventDate) entry.events.add(plain(meta.eventDate));
    if (meta.retrievedAt || known.retrievedAt || known.recordedAt) entry.retrievals.add(plain(meta.retrievedAt || known.retrievedAt || known.recordedAt));
    sourceRows.push(entry); sourceMap.set(url, entry); return entry.ref;
  }
  function linkLine(url, label, options = {}) {
    if (!urlOK(url)) return;
    const size = options.size || 8, lh = size * 1.35;
    font(size, 'normal', C.gold);
    const lines = doc.splitTextToSize(plain(label || url), CW);
    for (const line of lines) { ensure(lh); font(size, 'normal', C.gold); doc.text(line, M, y + size * 0.82); doc.link(M, y - 1, Math.min(CW, doc.getTextWidth(line)), lh, {url}); y += lh; }
    y += options.after ?? 4;
  }
  function refsLine(refs, note) { const unique = [...new Set(refs.filter(Boolean))]; if (unique.length || note) paragraph([unique.length ? 'Sources: ' + unique.map(r => `[${r}]`).join(' ') : '', note].filter(Boolean).join(' | '), {size: 8, color: C.muted}); }
  function recordSources(record) {
    const urls = [...list(record.sourceUrls), record.sourceUrl, ...list(record.sourceIds).map(s => sourceById.get(String(s))?.sourceUrl || sourceById.get(String(s))?.url)].filter(urlOK);
    return [...new Set(urls)].map(url => {
      const known = sourceByUrl.get(url) || {};
      const matchingDate = list(record.sourceDates).find(d => String(d.sourceId) === String(known.id));
      const ref = source(url, known.title || record.sourceTitle || record.title || 'District evidence', {publishedAt: matchingDate?.publishedAt || (record.recordType === 'official_legislation' ? undefined : record.publishedAt), eventDate: record.recordType === 'official_legislation' ? record.publishedAt : record.eventDate, retrievedAt: record.retrievedAt || known.retrievedAt, status: record.freshlyVerified ? 'Official record newly retrieved' : record.isGap ? 'Explicit evidence gap' : 'Imported historical evidence; source status retained'});
      return {url, ref};
    });
  }
  function drawMap(pathString, bb, tx, ty, tw, th) {
    if (!pathString || !Array.isArray(bb) || !bb[2] || !bb[3]) return false;
    const tokens = String(pathString).match(/[MLZmlz]|[-+]?(?:\d*\.\d+|\d+)(?:e[-+]?\d+)?/gi);
    if (!tokens) return false;
    const scale = Math.min(tw / bb[2], th / bb[3]), ox = tx + (tw - bb[2] * scale) / 2, oy = ty + (th - bb[3] * scale) / 2;
    const ops = []; let command = 'M';
    for (let i = 0; i < tokens.length;) {
      if (/^[MLZ]$/i.test(tokens[i])) { command = tokens[i++].toUpperCase(); if (command === 'Z') { ops.push({op: 'h', c: []}); continue; } }
      const x = Number(tokens[i++]), yy = Number(tokens[i++]); if (!Number.isFinite(x) || !Number.isFinite(yy)) continue;
      ops.push({op: command === 'M' ? 'm' : 'l', c: [ox + (x - bb[0]) * scale, oy + (yy - bb[1]) * scale]}); command = 'L';
    }
    if (!ops.length) return false;
    doc.setFillColor(...C.paleGold); doc.setDrawColor(...C.gold); doc.setLineWidth(0.55); doc.path(ops);
    if (doc.fillEvenOdd) doc.fillEvenOdd(); else doc.fill();
    doc.path(ops); doc.stroke(); return true;
  }

  // Cover and district overview.
  doc.setFillColor(...C.black); doc.rect(0, 0, W, 179, 'F');
  font(10, 'bold', C.paleGold); doc.text('THE SIXTY-THREE', M, 31);
  font(34, 'bold', C.white); doc.text(`DISTRICT ${String(id).padStart(2, '0')}`, M, 79);
  font(10, 'normal', [207, 213, 218]); doc.text('NEW YORK STATE SENATE', M, 102);
  font(9, 'normal', C.paleGold); doc.text('A sourced district dossier', M, 129);
  font(8, 'normal', [183, 191, 198]); doc.text(`Data edition ${plain(built)}  |  Evidence dates retained`, M, 151);
  drawMap(geometry.path || overlay.detailedPath, geometry.bounds || overlay.detailedBounds, W - 229, 28, 173, 118);
  y = 201;
  section('01', 'District overview', null, false);
  const overviewRef = source(data.directory?.meta?.sourceUrl, 'Official Senate directory and county coverage', {publishedAt: data.directory?.meta?.sourceDate, retrievedAt: data.directory?.meta?.retrievedOn, publisher: data.directory?.meta?.publisher});
  const mapRef = source(data.geometry?.metadata?.districtSource || data.geometry?.metadata?.sourceUrl || 'https://pubgeo.nysenate.gov/map/senate', 'Official New York State Senate district geography', {retrievedAt: data.geometry?.metadata?.retrieved});
  const officialRef = source(election.incumbent?.profileUrl, 'Official serving-member profile', {retrievedAt: profile.retrievedAt});
  const pop = metrics.find(x => x.key === 'population');
  table(['District context', 'Record'], [
    ['County coverage', directory.counties || list(election.counties).join(', ') || 'Not available'],
    ['Serving incumbent', election.incumbent?.name || (election.incumbent ? 'Not stated' : 'Vacant / no serving incumbent recorded')],
    ['Incumbent participation', election.incumbencyNote || (election.incumbentOnPrintedGeneralBallot ? 'Appeared on the printed general-election ballot' : 'Not on the printed general-election ballot')],
    ['2026 general-election field', `${list(election.candidates).length} printed candidates; ${election.unopposedOnPrintedBallot ? 'unopposed on printed ballot' : 'contested on printed ballot'}`],
    ['2026 leading candidate', `${election.leadingCandidate || 'Not stated'} - unofficial; lead ${number(election.leadVotes)} votes / ${number(election.leadPercentagePoints, 2)} percentage points`],
    ['Population estimate', pop ? `${number(pop.value)} +/- ${number(pop.moe)} people, ${plain(pop.period)} ACS; ${pop.moeConfidence || 90}% confidence` : 'Fresh ACS data not included in this build'],
    ['Dossier coverage', `${evidence.length} district evidence records; ${metrics.length} ACS metrics; ${finance.coveredCandidates ?? 0}/${finance.candidateCount ?? list(election.candidates).length} general candidates with finance records`],
  ], [31, 69]);
  refsLine([overviewRef, mapRef, officialRef]);
  paragraph('This dossier preserves the distinction between office-holding, unofficial election returns, certified historical results, public filings, statistical estimates and imported research. A missing field is an evidence gap, not zero or a negative finding.', {size: 9.2, color: C.muted});
  subheading('Reading guide');
  paragraph('Election record / Campaign finance / Issue evidence / People and households / Official member and legislative activity / Geography and migration / Source registry and methods', {size: 9.3});

  // Elections: all candidates and ballot lines, certification states, primaries and documented nonparticipants.
  section('02', 'Election record', 'Current returns and certified historical contests are shown with their own source dates and definitions.');
  const eRef = source(election.sourceUrl || data.elections?.meta?.sourceUrl, '2026 general election - official BOE unofficial returns', {publishedAt: election.sourceUpdatedAt || data.elections?.meta?.sourceUpdatedAt, retrievedAt: data.elections?.meta?.retrievedOn, publisher: 'New York State Board of Elections', status: election.status});
  subheading('2026 general election - unofficial');
  paragraph(`Election date: ${date(election.electionDate)}. Source updated: ${date(election.sourceUpdatedAt)}. ${plain(election.status)}.`, {size: 9.2});
  table(['Candidate / ballot lines', 'Votes', 'Valid vote share', 'Incumbent / result'], list(election.candidates).map(c => [c.name + '\n' + list(c.ballotLines).map(b => `${b.party}: ${number(b.votes)}`).join('; '), number(c.votes), number(c.shareOfValidVotes, 2) + '%', `${c.incumbent ? 'Incumbent' : 'Challenger / new candidate'}\n${c.resultStatus || 'Unofficial'}`]), [43, 15, 16, 26]);
  table(['Reporting measure', 'Value'], [['Total ballots', number(election.totalBallots)], ['Valid votes, including aggregate write-ins', number(election.validVotes)], ['Active registered voters', number(election.activeRegisteredVoters)], ['Reporting election districts', `${number(election.electionDistrictsReporting)} / ${number(election.electionDistrictsTotal)} (${number(election.reportingPercent, 2)}%)`], ['Blank / void / write-in ballots', Object.entries(election.otherBallots || {}).map(([k, v]) => `${titleCase(k)}: ${number(v)}`).join('; ')]], [57, 43]);
  refsLine([eRef], data.elections?.meta?.voteShareMethod);
  if (data.elections?.meta?.statewideCaution) paragraph(data.elections.meta.statewideCaution, {size: 8.8, color: C.muted});
  const h = election.history2024;
  subheading('2024 general election - certified history');
  if (h) {
    const hRef = source(h.sourceUrl, '2024 certified general-election results', {eventDate: h.electionDate, publisher: 'New York State Board of Elections', status: h.status});
    table(['Candidate / ballot lines', 'Votes', 'Valid vote share', 'Certified result'], list(h.candidates).map(c => [c.name + '\n' + list(c.ballotLines).map(b => `${b.party}: ${number(b.votes)}`).join('; '), number(c.votes), number(c.shareOfValidVotes, 2) + '%', c.resultStatus || (c.winner ? 'Won - certified' : 'Lost - certified')]), [45, 15, 16, 24]);
    paragraph(`Certified winner: ${h.winner || 'Not stated'}. Margin: ${number(h.marginVotes)} votes / ${number(h.marginPercentagePoints, 2)} points. Total ballots: ${number(h.totalBallots)}.`, {size: 9}); refsLine([hRef]);
  } else paragraph('No certified 2024 record is included for this district.');
  subheading('2026 primaries');
  if (list(election.primaryElections).length) for (const primary of election.primaryElections) {
    paragraph(`${primary.party || 'Party not stated'} primary | ${date(primary.electionDate)} | ${plain(primary.status)}`, {bold: true, size: 9.5});
    table(['Candidate', 'Votes', 'Valid vote share', 'Result'], list(primary.candidates).map(c => [c.name, number(c.votes), number(c.shareOfValidVotes, 2) + '%', c.resultStatus || (c.winner ? 'Won primary' : 'Did not win primary')]), [42, 16, 18, 24]);
    refsLine([source(primary.sourceUrl, 'Certified 2026 primary result', {eventDate: primary.electionDate, status: primary.status, publisher: 'New York State Board of Elections'})]);
  } else paragraph('No contested-primary return was collected for this district. This does not establish that no nomination process occurred.');
  subheading('Primary non-advancers and documented nonparticipation');
  const non = [...list(election.primaryNonAdvancers), ...list(election.nonContestants)];
  if (non.length) for (const n of non) {
    paragraph(`${n.name || n.candidate || 'Record'}: ${n.status || n.reason || n.note || 'See source'}. ${n.votes !== undefined ? `Primary votes: ${number(n.votes)}.` : ''}`, {size: 9.2});
    refsLine([source(n.sourceUrl, 'Primary non-advancer / documented nonparticipation', {eventDate: n.primaryDate || n.date})]);
  } else paragraph(election.nonContestantsStatus || 'No independently sourced withdrawal or nonparticipation record has been added. Absence from the printed ballot is not, by itself, a documented withdrawal.');

  // Finance: every general candidate is represented, including gaps.
  section('03', 'Campaign finance', `Gross disclosed monetary contributions in ${finance.period || data.finance?.meta?.period || 'the stated filing window'}. Rankings are within each candidate's collected committee group.`);
  const fRef = source(finance.sourceUrl || data.finance?.meta?.sourceUrl, 'NYS BOE campaign-finance disclosures', {retrievedAt: data.finance?.meta?.retrievedAt, publishedAt: data.finance?.meta?.sourceUpdatedAt, publisher: 'New York State Board of Elections'});
  paragraph(finance.note || 'Candidate-level collection coverage is shown below.', {size: 9.2});
  const normalizedName = name => plain(name).toLowerCase().replace(/[^a-z0-9]/g, '');
  const fCandidates = list(finance.candidates);
  const orderedFinance = list(election.candidates).map(c => fCandidates.find(f => normalizedName(f.name) === normalizedName(c.name)) || {name: c.name, available: false, note: 'No contribution dataset was collected for this candidate.'});
  for (const c of fCandidates) if (!orderedFinance.includes(c)) orderedFinance.push(c);
  for (const c of orderedFinance) {
    subheading(c.name || 'Candidate');
    if (!c.available && c.totalContributions === undefined) { paragraph(c.note || c.status || 'No candidate finance data collected. Missing is not zero.'); continue; }
    paragraph(`Committee group: ${c.committeeName || list(c.committees).map(x => x.name).join('; ') || 'Not stated'}. Total: ${money(c.totalContributions)}. Transactions: ${number(c.transactionCount)}. Named donor groups: ${number(c.namedDonorGroups)}.`, {size: 9.1});
    paragraph(`Window: ${c.period || finance.period || 'Not stated'}. Latest transaction: ${date(c.lastTransactionDate)}. Mapping: ${titleCase(c.committeeMappingStatus || 'basis recorded in source')}. Unitemized / unnamed amount: ${money(c.unitemizedOrUnnamedAmount)}.`, {size: 8.5, color: C.muted});
    table(['Rank / disclosed contributor', 'Type', 'Amount', 'Transactions / dates'], list(c.donors).slice(0, 10).map((d, i) => [`${i + 1}. ${d.name}`, d.type || 'Not stated', money(d.amount), `${number(d.transactions)}\n${date(d.firstDate)} to ${date(d.lastDate)}`]), [38, 20, 17, 25]);
    if (!list(c.donors).length) paragraph('No named donor ranking is available for this candidate.', {size: 9});
    const cr = source(c.sourceUrl, `${c.name}: contribution query`, {retrievedAt: data.finance?.meta?.retrievedAt, status: c.status});
    const mr = source(c.committeeMappingSource, `${c.name}: official committee identity / authorization`, {retrievedAt: data.finance?.meta?.retrievedAt});
    refsLine([fRef, cr, mr], c.note);
  }

  // All 20 tracks, then every district record exactly once, retaining multiple topic tags.
  section('04', 'Issue evidence', 'The topic index shows collection coverage. Counts describe records in this terminal; they do not measure voter opinion, importance, support or opposition.');
  table(['Track', 'Issue', 'District records', 'Fresh official records'], issues.map(i => {
    const rr = evidence.filter(r => list(r.issueIds).map(Number).includes(Number(i.id)));
    return [String(i.id).padStart(2, '0'), i.title, String(rr.filter(r => !r.isGap).length), String(rr.filter(r => r.freshlyVerified && !r.isGap).length)];
  }), [8, 57, 17, 18]);
  paragraph('Records below appear once. Every linked issue number is retained, so a multi-topic statement is not duplicated as if it were several independent findings.', {size: 8.8, color: C.muted});
  if (!evidence.length) paragraph('No structured district issue records are included in this build.');
  const orderedEvidence = [...evidence].sort((a, b) => (Number(a.isGap) - Number(b.isGap)) || (Math.min(...list(a.issueIds).map(Number), 99) - Math.min(...list(b.issueIds).map(Number), 99)) || String(a.publishedAt || '').localeCompare(String(b.publishedAt || '')));
  orderedEvidence.forEach((r, index) => {
    ensure(88); rule();
    const trackLabels = list(r.issueIds).map(i => `${String(i).padStart(2, '0')} ${issues.find(t => Number(t.id) === Number(i))?.title || ''}`).join(' / ');
    paragraph(`${String(index + 1).padStart(2, '0')}  ${r.isGap ? 'EVIDENCE GAP' : plain(r.evidenceType || r.recordType || 'District evidence').toUpperCase()}`, {size: 8.5, bold: true, color: C.gold, after: 5});
    if (trackLabels) paragraph('Issue tracks: ' + trackLabels, {size: 8, color: C.muted, after: 6});
    if (r.candidate || list(r.candidates).length) paragraph('Named candidate / member: ' + (r.candidate || list(r.candidates).join('; ')), {size: 9.2, bold: true, after: 5});
    paragraph(r.summary || r.title || r.description || 'No summary provided.', {size: 10});
    const sourceDates = list(r.sourceDates).map(d => `${d.sourceId || 'source'}: ${d.publishedAt || 'date not stated'}`).join('; ');
    paragraph(`Source / event date: ${date(r.publishedAt || r.eventDate)}. ${sourceDates ? `Referenced source dates: ${sourceDates}. ` : ''}Retrieved: ${date(r.retrievedAt)}. ${r.handoffSnapshotAt ? `Handoff snapshot: ${date(r.handoffSnapshotAt)}. ` : ''}${r.freshlyVerified ? 'Newly retrieved official evidence.' : 'Imported evidence; not automatically a fresh verification.'}`, {size: 8.1, color: C.muted});
    if (r.associationMethod) paragraph('Association: ' + r.associationMethod, {size: 8, color: C.muted});
    for (const note of list(r.limitations)) paragraph('Limit: ' + note, {size: 8, color: C.muted, after: 4});
    const rr = recordSources(r);
    if (rr.length) for (const s of rr) linkLine(s.url, `[${s.ref}] ${s.url}`, {size: 7.6});
    else paragraph('No direct source URL attached to this record.', {size: 8, color: C.muted});
  });

  // All ACS metrics and their universes / margins of error.
  section('05', 'People and households', `${data.census?.meta?.period || '2020-2024'} American Community Survey five-year estimates. All ${metrics.length} available district metrics are included; margins of error are at ${data.census?.meta?.moeConfidence || 90}% confidence.`);
  const metricValue = (value, unit) => value === null || value === undefined ? 'Not available' : (unit?.startsWith('USD') ? '$' : '') + number(value, unit === 'percent' || unit === 'years' ? 2 : 0) + (unit === 'percent' ? '%' : '');
  const metricRows = metrics.map(m => {
    const ref = source(m.officialSourceUrl || m.sourceUrl, `ACS table ${m.table}: ${m.label}`, {publishedAt: m.period, retrievedAt: m.retrievedAt, publisher: 'U.S. Census Bureau', status: m.evidenceType});
    source(m.sourceUrl, `Census-origin API data: table ${m.table}`, {publishedAt: m.period, retrievedAt: m.retrievedAt, publisher: 'Census Reporter, distributing U.S. Census Bureau tables'});
    return [`${m.label}\n${m.unit || ''}`, metricValue(m.value, m.unit), m.moe === null || m.moe === undefined ? 'Not available' : '+/- ' + metricValue(m.moe, m.unit), `${m.universe || 'Universe not stated'}${m.note ? '\n' + m.note : ''}${m.quality?.includes('high') ? '\nHIGH SAMPLING UNCERTAINTY' : ''}`, `${m.table || ''}\n[${ref}]`];
  });
  table(['Metric / unit', 'Estimate', '90% MOE', 'Statistical universe / note', 'Table / source'], metricRows, [29, 14, 15, 31, 11], {size: 8.1, pad: 4.5});
  if (!metrics.length) paragraph('Fresh district Census metrics were not included in this build.');
  paragraph('MOEs beside percentages are percentage points. Derived sums and percentages have approximate MOEs; the formulas do not capture all covariance. ACS estimates describe the survey period and are not live 2026 counts. They do not establish religious affiliation or political preferences.', {size: 9.2, color: C.muted});
  const acsMethodRef = source(data.census?.meta?.methodologyUrl, 'ACS margins of error and derived-estimate methods', {publisher: 'U.S. Census Bureau'});
  refsLine([acsMethodRef]);

  // Current member profile and recorded institutional activity.
  section('06', 'Official member and activity', 'Serving-member records are distinct from election outcomes. Committee roles and biographies are office-published records with their own retrieval dates.');
  subheading(profile.name || election.incumbent?.name || 'No serving member recorded');
  paragraph(profile.profileStatus || election.incumbent?.sourceStatus || 'Official profile coverage not stated.', {size: 9.2});
  const pRef = source(profile.aboutUrl || profile.profileUrl || election.incumbent?.profileUrl, 'Official member biography and committee assignments', {retrievedAt: profile.retrievedAt, publisher: 'New York State Senate', status: profile.biographyAttribution || 'Office-authored profile'});
  table(['Public office contact', 'Record'], [['District office', directory.districtOfficeAddress || geometry.contacts?.address || 'Not available'], ['District telephone', directory.districtPhone || geometry.contacts?.districtPhone || 'Not available'], ['Albany telephone', directory.albanyPhone || geometry.contacts?.albanyPhone || 'Not available'], ['Official email', directory.email || geometry.contacts?.email || 'Not available'], ['Profile retrieved', date(profile.retrievedAt)]], [32, 68]);
  if (profile.biographyAvailable || profile.biography || profile.biographyExcerpt) {
    const words = plain(profile.biographyExcerpt || profile.biography).split(/\s+/);
    paragraph('Official biography excerpt: "' + words.slice(0, 23).join(' ') + (words.length > 23 ? '...' : '') + '"', {size: 9.2});
    paragraph('The linked office-authored biography contains the complete career, education and public-service narrative; its claims are attributed to the member\'s office.', {size: 8.7, color: C.muted});
    if (profile.aboutUrl || profile.profileUrl) linkLine(profile.aboutUrl || profile.profileUrl, 'Read the complete official biography');
  }
  if (list(profile.committees).length) table(['Committee', 'Role'], profile.committees.map(c => [c.name, c.role]), [72, 28]);
  else paragraph('No committee assignment list was collected for this profile.');
  refsLine([pRef]);
  subheading('District-linked legislative records');
  const bills = list(data.issueEvidence?.legislation).filter(b => Number(b.sponsor?.district) === id || list(b.cosponsors).some(c => Number(c.district) === id) || list(b.rollCalls).some(r => list(r.members).some(m => Number(m.district) === id)) || list(b.districts).map(Number).includes(id));
  if (bills.length) {
    const billRows = bills.map(b => {
      const relationships = [];
      if (Number(b.sponsor?.district) === id) relationships.push(`Sponsor: ${b.sponsor.name}`);
      for (const c of list(b.cosponsors).filter(c => Number(c.district) === id)) relationships.push(`Co-sponsor: ${c.name}`);
      for (const call of list(b.rollCalls)) for (const m of list(call.members).filter(m => Number(m.district) === id)) relationships.push(`${call.date || 'Date not stated'} ${call.type || 'vote'}: ${m.name || m.nameAsPublished} - ${titleCase(m.vote)}`);
      const ref = source(b.sourceUrl, `${b.billId || b.id}: ${b.title}`, {publishedAt: b.publishedAt, retrievedAt: b.retrievedAt, publisher: b.publisher, status: b.evidenceType});
      return [`${b.billId || b.id}\n${b.title}`, relationships.join('\n') || 'District association recorded', `${b.currentStatus || ''}\n${b.latestAction?.date || ''} ${b.latestAction?.action || ''}\nRetrieved ${b.retrievedAt || 'not stated'}`, `[${ref}]`];
    });
    table(['Bill / title', 'District association / named vote', 'Latest recorded action', 'Ref.'], billRows, [31, 36, 25, 8], {size: 8.2});
    paragraph('A recorded vote is assigned to the named senator on its event date. It does not establish a later candidate\'s position. A co-sponsor list may be incomplete. Bill status is the source snapshot, not a guarantee of subsequent enactment.', {size: 8.8, color: C.muted});
  } else paragraph('No district-linked bill sponsorship or named roll-call record was collected in this build.');

  // Context that enriches the district without creating false geographic crosswalks.
  section('07', 'Geography and migration', 'District boundaries, neighborhood statistics and county migration describe different geographic units. Their labels are preserved.');
  paragraph(`Official county coverage: ${directory.counties || list(election.counties).join(', ') || 'Not available'}.`, {bold: true});
  if (list(overlay.neighborhoods).length) {
    paragraph(`${overlay.detailedBoundaryScope || 'NYC district geography'}. ${overlay.neighborhoodCount ?? overlay.neighborhoodNames?.length ?? 0} residential NTAs; ${overlay.specialAreaCount ?? 0} special-area NTAs; ${overlay.electionDistrictCount ?? list(overlay.electionDistricts).length} official election-district outlines. No ED vote totals are inferred from boundary geometry.`, {size: 9.2});
    table(['Neighborhood tabulation area', 'Borough', 'Clipped area (km2)', 'Part of NTA'], list(overlay.neighborhoods).map(n => [n.name + (n.typeCode !== '0' ? '\nSpecial-area NTA' : ''), n.borough, number(n.areaKm2, 3), number(n.shareOfSourceAreaPct, 1) + '%']), [47, 18, 18, 17], {size: 8.4});
    refsLine(list(data.overlays?.metadata?.sources).map(s => source(s.url || s.sourceUrl, s.title, {publishedAt: s.sourceUpdatedAt, retrievedAt: s.retrievedAt, publisher: s.publisher})), 'NTAs approximate neighborhoods; percentages are geometric area, not population weights.');
  } else paragraph('The collected NTA and ED overlays cover New York City. This district is outside that dataset coverage; its statewide Senate boundary remains available.', {size: 9.2});
  const countyContext = find(migration.districtCountyContext);
  if (countyContext) {
    subheading('Whole-county migration context');
    paragraph(countyContext.geographicCaution, {size: 9.2, color: C.muted});
    const mr = [];
    for (const c of list(countyContext.countyContext)) {
      const r = list(migration.countyMigration).filter(x => x.countyFips === c.countyFips).sort((a, b) => String(b.vintage).localeCompare(String(a.vintage)))[0];
      if (r) {
        mr.push([c.countyName, r.period, number(r.inflow?.returns), number(r.outflow?.returns), number(r.net?.returns), money(r.net?.agiUsd)]);
        for (const sid of list(r.sourceIds)) { const s = list(migration.sources).find(s => s.id === sid); if (s) source(s.url || s.sourceUrl, s.title, {publishedAt: s.dataVintage, retrievedAt: s.retrievedAt, publisher: s.publisher}); }
      }
    }
    table(['Whole county', 'IRS vintage', 'Returns in', 'Returns out', 'Net returns', 'Net mover AGI'], mr, [24, 14, 14, 14, 14, 20], {size: 8.1});
    paragraph('IRS returns approximate households and AGI is movers\' adjusted gross income, not lost tax revenue. These county totals include areas outside the district. Matching methodology changed beginning in 2022-2023.', {size: 9, color: C.muted});
  }
  const districtMedia = list(data.handoff?.media).filter(m => list(m.districts).map(Number).includes(id));
  if (districtMedia.length) {
    subheading('Explicitly district-tagged media references');
    for (const m of districtMedia) {
      paragraph(`${m.platform} | ${m.publisher} | ${m.publishedAtLabel || 'Date not stated'}\n${m.summary}`, {size: 9.1});
      const ref = source(m.sourceUrl, `${m.platform}: ${m.publisher}`, {publishedAt: m.publishedAtLabel, retrievedAt: m.recordedAt, status: m.verificationStatus});
      linkLine(m.sourceUrl, `[${ref}] ${m.sourceUrl}`, {size: 7.8});
      paragraph(m.verificationStatus || 'Historical handoff media reference.', {size: 8, color: C.muted});
    }
  }

  // Bibliography contains the exact URLs behind citations; annotations make them clickable.
  section('08', 'Source registry', 'Every reference used in this district dossier is listed below with its URL and available dates. Publication, retrieval and event dates are separate fields.');
  for (const s of sourceRows) {
    ensure(58); paragraph(`[${s.ref}] ${s.title}`, {bold: true, size: 9.1, after: 3});
    const metadata = [s.publisher, s.dates.size ? 'Source / publication date: ' + [...s.dates].join('; ') : 'Source / publication date: not stated', s.events.size ? 'Event date: ' + [...s.events].join('; ') : '', s.retrievals.size ? 'Retrieved / recorded: ' + [...s.retrievals].join('; ') : 'Retrieval date: not stated'].filter(Boolean).join(' | ');
    paragraph(metadata, {size: 7.8, color: C.muted, after: 4});
    if (s.status) paragraph(s.status, {size: 7.7, color: C.muted, after: 3});
    linkLine(s.url, s.url, {size: 7.4, after: 9});
  }

  section('09', 'Methods and evidence limits', 'Read these definitions alongside the tables. This export records the evidence available in the terminal build and does not certify the underlying election or filing data.');
  subheading('Election interpretation');
  for (const s of [data.elections?.meta?.status, data.elections?.meta?.fusionVotingMethod, data.elections?.meta?.voteShareMethod, data.elections?.meta?.incumbencyMethod, data.elections?.meta?.statewideCaution].filter(Boolean)) paragraph(s, {size: 9});
  subheading('Campaign-finance method');
  const financeMethods = list(data.finance?.meta?.methodology);
  for (const s of financeMethods.length ? financeMethods : ['Rankings show collected gross monetary contributions, not cash on hand. Missing candidate coverage is not zero.']) paragraph(s, {size: 9});
  subheading('Census method');
  for (const s of list(data.census?.meta?.notes)) paragraph(s, {size: 9});
  subheading('Issue and geographic evidence');
  for (const s of [data.issueEvidence?.meta?.methodology, ...list(data.issueEvidence?.meta?.limitations), ...list(data.overlays?.metadata?.limits), ...list(migration.metadata?.limits)].filter(Boolean)) paragraph(s, {size: 9});
  paragraph('An office biography is attributed to its authoring office. A historical media link is a collected reference, not a live social-media feed. A collection gap does not imply that an event, candidacy, contribution, position or demographic group does not exist. No demographic or ancestry statistic establishes individual identity, religion or political preference.', {size: 9});
  rule(); paragraph(`Compiled for The Sixty-Three. District ${id}. Data edition ${plain(built)}. Document length follows the available evidence; no fixed page cap or artificial page padding is applied.`, {size: 8.7, color: C.muted});

  const totalPages = doc.internal.getNumberOfPages();
  for (let page = 1; page <= totalPages; page++) {
    doc.setPage(page); doc.setDrawColor(...C.line); doc.setLineWidth(0.5); doc.line(M, H - 31, W - M, H - 31);
    font(7.3, 'normal', C.muted); doc.text(`THE SIXTY-THREE  |  SD ${String(id).padStart(2, '0')}  |  ${plain(built)}`, M, H - 17);
    doc.text(`${page} / ${totalPages}`, W - M, H - 17, {align: 'right'});
  }
  doc.setPage(1);
  return doc;
}
